def setup(inst, name):
    p = stream.Part(id=name.replace(' ', '_').lower())
    p.partName = name
    p.insert(0, inst)
    p.insert(0, meter.TimeSignature('4/4'))
    p.insert(0, key.KeySignature(-1))
    p.insert(0, tempo.MetronomeMark(number=72, text='Andante, breathing'))
    return p

def add_event(p, x, d):
    if x is None:
        p.append(note.Rest(quarterLength=d))
    elif isinstance(x, (list, tuple)):
        p.append(chord.Chord(x, quarterLength=d))
    else:
        p.append(note.Note(x, quarterLength=d))

def add_measure(p, events):
    total = 0
    for x, d in events:
        add_event(p, x, d)
        total += d
    if abs(total - 4.0) > 0.001:
        raise ValueError('measure does not equal 4 quarter notes')

