from music21 import (stream, note, duration, instrument, tempo, key, meter,
                     dynamics, expressions, clef, metadata, pitch)

# What Stays -- a passacaglia in D minor.
# An eight-bar ground bass repeats without change while the texture above it
# grows from solitude to radiance and dissolves again.

score = stream.Score()
md = metadata.Metadata()
md.title = 'What Stays'
md.composer = 'Kimi'
score.insert(0, md)

# The ground: eight bars, never altered.
GROUND = [
    [('D3', 2), ('D3', 1), ('A2', 1)],
    [('C3', 2), ('C3', 1), ('G2', 1)],
    [('B-2', 2), ('B-2', 1), ('F2', 1)],
    [('A2', 2), ('A2', 1), ('E2', 1)],
    [('G2', 2), ('G2', 1), ('D2', 1)],
    [('F2', 2), ('F2', 1), ('C2', 1)],
    [('E2', 2), ('E2', 1), ('B2', 1)],
    [('A2', 2), ('A2', 1), ('E2', 1)],
]

# Chord-tone palettes, register chosen per instrument.
V2_TONES = [
    ['D4', 'F4', 'A4'], ['C4', 'E4', 'G4'], ['B-3', 'D4', 'F4'],
    ['A3', 'C#4', 'E4'], ['G3', 'B-3', 'D4'], ['A3', 'C4', 'F4'],
    ['B-3', 'E4', 'G4'], ['A3', 'C#4', 'E4'],
]
VA_TONES = [
    ['F3', 'A3'], ['E3', 'G3'], ['D3', 'F3'], ['C#3', 'E3'],
    ['D3', 'B-3'], ['A3', 'F3'], ['G3', 'B-3'], ['A3', 'C#4'],
]
VA_C5 = [
    ['A3', 'D4', 'F4'], ['G3', 'C4', 'E4'], ['F3', 'B-3', 'D4'],
    ['E3', 'A3', 'C#4'], ['G3', 'B-3', 'D4'], ['F3', 'A3', 'C4'],
    ['G3', 'B-3', 'E4'], ['E3', 'A3', 'C#4'],
]

# The first violin's song (cycles 4 and 5) and its farewell (cycle 6).
V1_C4 = [
    [('F4', 2), ('G4', 1), ('A4', 1)],
    [('G4', 3), ('A4', 1)],
    [('B-4', 2), ('A4', 1), ('G4', 1)],
    [('C#5', 2), ('A4', 2)],
    [('D5', 3), ('C5', 1)],
    [('E5', 2), ('D5', 1), ('C5', 1)],
    [('D5', 2), ('C5', 1), ('B-4', 1)],
    [('C#5', 4)],
]
V1_C5 = [
    [('D5', 2), ('E5', 1), ('F5', 1)],
    [('E5', 2), ('G5', 2)],
    [('F5', 3), ('E5', 1)],
    [('E5', 4)],
    [('F5', 2), ('G5', 1), ('A5', 1)],
    [('G5', 2), ('E5', 2)],
    [('F5', 4)],
    [('E5', 4)],
]
V1_C6 = [
    [('A4', 2), ('F4', 2)],
    [('G4', 4)],
    [('F4', 4)],
    [('E4', 4)],
]

# The coda: the ground breaks; minor becomes major (Picardy third).
CODA = {
    'vc': ['D3', 'D3', 'A2', 'D3'],
    'va': ['F3', 'F#3', 'E3', 'F#3'],
    'v2': ['A3', 'A3', 'C#4', 'D4'],
    'v1': [None, 'D5', 'A4', 'D5'],
}


def up8(pname):
    return pitch.Pitch(pname).transpose(12).nameWithOctave


V2_TONES_UP = [[up8(t) for t in row] for row in V2_TONES]


def vel_for(i):
    if i <= 8:
        return 42
    if i <= 16:
        return 54
    if i <= 24:
        return 64
    if i <= 32:
        return 76
    if i <= 36:
        return 90
    if i <= 40:
        return 100
    if i <= 44:
        return 55
    if i <= 48:
        return 44
    return 36


def make_element(pname, qlen, vel):
    if pname is None:
        el = note.Rest()
    else:
        el = note.Note(pname)
        el.volume.velocity = vel
    el.duration = duration.Duration(qlen)
    return el


def fill_measure(m, events, vel, dyn=None, text=None, tmark=None):
    for pname, qlen in events:
        m.append(make_element(pname, qlen, vel))
    if dyn is not None:
        m.insert(0, dynamics.Dynamic(dyn))
    if text is not None:
        m.insert(0, expressions.TextExpression(text))
    if tmark is not None:
        m.insert(0, tmark)


def wave_events(tones, kind):
    t0, t1, t2 = tones
    if kind == 'A':
        seq = [t0, t1, t2, t1, t0, t1, t2, t1]
    else:
        seq = [t2, t1, t0, t1, t2, t1, t0, t1]
    return [(p, 0.5) for p in seq]


def cello_events(i):
    if i <= 48:
        cycle = (i - 1) // 8
        pos = (i - 1) % 8
        if cycle == 5 and pos >= 4:  # even the ground begins to tire
            return [(GROUND[pos][0][0], 2), (None, 2)]
        return GROUND[pos]
    return [(CODA['vc'][i - 49], 4)]


def viola_events(i):
    if i <= 8:
        return [(None, 4)]
    pos = (i - 1) % 8
    t = VA_TONES[pos]
    if i <= 16:
        return [(t[0], 2), (t[1], 2)]
    if i <= 24:
        return [(t[0], 2), (t[0], 1), (t[1], 1)]
    if i <= 32:
        return [(t[0], 1), (t[1], 1), (t[1], 2)]
    if i <= 40:
        return wave_events(VA_C5[pos], 'B' if pos % 2 == 0 else 'A')
    if i <= 48:
        return [(t[0], 2), (t[1], 2)]
    return [(CODA['va'][i - 49], 4)]


def violin2_events(i):
    if i <= 16:
        return [(None, 4)]
    pos = (i - 1) % 8
    if i <= 24:
        return wave_events(V2_TONES[pos], 'A' if pos % 2 == 0 else 'B')
    if i <= 32:
        t0, t1, t2 = V2_TONES[pos]
        return [(None, 1), (t2, 0.5), (t1, 0.5), (t0, 0.5),
                (t1, 0.5), (t2, 0.5), (t1, 0.5)]
    if i <= 40:
        return wave_events(V2_TONES_UP[pos], 'A' if pos % 2 == 0 else 'B')
    if i <= 48:
        if pos < 4:
            t = V2_TONES[pos]
            return [(t[0], 2), (t[2], 2)]
        return [(None, 4)]
    return [(CODA['v2'][i - 49], 4)]


def violin1_events(i):
    if i <= 24:
        return [(None, 4)]
    pos = (i - 1) % 8
    if i <= 32:
        return V1_C4[pos]
    if i <= 40:
        return V1_C5[pos]
    if i <= 48:
        return V1_C6[pos] if pos < 4 else [(None, 4)]
    p = CODA['v1'][i - 49]
    return [(p, 4)] if p else [(None, 4)]


def flute_events(i):
    if i <= 32:
        return [(None, 4)]
    if i <= 40:
        pos = (i - 1) % 8
        if pos == 7:
            return [(None, 4)]
        return [(up8(p), q) for (p, q) in V1_C5[pos]]
    return [(None, 4)]


VC_DYN = {1: 'pp', 9: 'p', 17: 'mp', 25: 'mf', 33: 'f', 37: 'ff',
          41: 'p', 45: 'pp', 49: 'ppp'}
VA_DYN = {9: 'p', 17: 'mp', 25: 'mf', 33: 'f', 37: 'ff',
          41: 'p', 45: 'pp', 49: 'ppp'}
V2_DYN = {17: 'mp', 25: 'mf', 33: 'f', 37: 'ff', 41: 'p', 49: 'ppp'}
V1_DYN = {25: 'mf', 33: 'f', 37: 'ff', 41: 'p', 50: 'ppp'}
FL_DYN = {33: 'f', 37: 'ff'}

VC_TXT = {1: 'semplice, come un respiro', 17: 'poco a poco animando'}
V1_TXT = {25: 'espressivo', 33: 'con slancio', 41: 'calando'}
FL_TXT = {1: 'Andante con moto', 33: 'brillante', 49: 'rit. e morendo'}

FL_MM = {1: tempo.MetronomeMark(number=76), 49: tempo.MetronomeMark(number=58)}

PARTS = [
    ('Flute', instrument.Flute(), clef.TrebleClef(),
     flute_events, FL_DYN, FL_TXT, FL_MM),
    ('Violin I', instrument.Violin(), clef.TrebleClef(),
     violin1_events, V1_DYN, V1_TXT, {}),
    ('Violin II', instrument.Violin(), clef.TrebleClef(),
     violin2_events, V2_DYN, {}, {}),
    ('Viola', instrument.Viola(), clef.AltoClef(),
     viola_events, VA_DYN, {}, {}),
    ('Violoncello', instrument.Violoncello(), clef.BassClef(),
     cello_events, VC_DYN, VC_TXT, {}),
]

for name, inst, clf, event_fn, dyn_map, text_map, mm_map in PARTS:
    part = stream.Part(id=name)
    part.partName = name
    part.append(inst)
    part.append(clf)
    part.append(key.Key('d'))
    part.append(meter.TimeSignature('4/4'))
    for i in range(1, 53):
        m = stream.Measure(number=i)
        fill_measure(m, event_fn(i), vel_for(i),
                     dyn=dyn_map.get(i), text=text_map.get(i),
                     tmark=mm_map.get(i))
        if i == 52:
            for sounding in m.notes:
                sounding.expressions.append(expressions.Fermata())
        part.append(m)
    score.append(part)
